args.sparql:
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?album ?albumLabel ?rstr ?year WHERE {
  VALUES ?album { dbr:Los_Monsters dbr:Wake_of_the_Flood }
  OPTIONAL { ?album dbo:releaseDate ?rd . }
  OPTIONAL { ?album dbp:released ?rp . }
  OPTIONAL { ?album dbp:releasedDate ?rpd . }
  BIND(COALESCE(STR(?rd), STR(?rp), STR(?rpd)) AS ?rstr)
  FILTER(BOUND(?rstr))
  BIND(
    IF(regex(?rstr, "^[0-9]{4}"),
       xsd:integer(SUBSTR(?rstr, 1, 4)),
       IF(regex(?rstr, "[0-9]{4}$"),
          xsd:integer(SUBSTR(?rstr, STRLEN(?rstr)-3, 4)),
          xsd:integer("0")
       )
    ) AS ?year
  )
  OPTIONAL { ?album rdfs:label ?albumLabel . FILTER(lang(?albumLabel) = "en") }
}
ORDER BY ?year
LIMIT 1

